#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <linux/bpf.h>
#include <sys/syscall.h>
#include <stdint.h>
#include <sys/mman.h>

#ifndef __NR_bpf
#define __NR_bpf 321
#endif

// Wrappers
int bpf_map_create(enum bpf_map_type map_type, int key_size, int value_size, int max_entries) {
    union bpf_attr attr = {
        .map_type = map_type,
        .key_size = key_size,
        .value_size = value_size,
        .max_entries = max_entries,
    };
    return syscall(__NR_bpf, BPF_MAP_CREATE, &attr, sizeof(attr));
}

int bpf_prog_load(enum bpf_prog_type prog_type, const struct bpf_insn *insns, int insn_cnt, const char *license) {
    union bpf_attr attr = {
        .prog_type = prog_type,
        .insns = (uint64_t)insns,
        .insn_cnt = insn_cnt,
        .license = (uint64_t)license,
        .log_level = 7,
        .log_buf = (uint64_t)malloc(1024*1024),
        .log_size = 1024*1024,
    };
    int ret = syscall(__NR_bpf, BPF_PROG_LOAD, &attr, sizeof(attr));
    if (ret < 0) {
        printf("bpf_prog_load failed: %s\n", strerror(errno));
        printf("Verifier log:\n%s\n", (char *)attr.log_buf);
    }
    return ret;
}

int main() {
    // Create RINGBUF map
    int ringbuf_fd = bpf_map_create(BPF_MAP_TYPE_RINGBUF, 0, 0, 4096);
    if (ringbuf_fd < 0) {
        perror("bpf_map_create RINGBUF");
        // RINGBUF might require max_entries to be page aligned
    }
    printf("RINGBUF fd: %d\n", ringbuf_fd);

    // Construct instructions based on reproducer
    // 28 instructions
    struct bpf_insn insns[28];
    memset(insns, 0, sizeof(insns));

    // Insn 0: r8 = 0xff80 (LD_IMM64)
    insns[0].code = BPF_LD | BPF_IMM | BPF_DW;
    insns[0].dst_reg = 8;
    insns[0].imm = 0x0000ff80; // This is what blob says: 80 ff 00 00
    // Insn 1: 0 (Part 2 of LD_IMM64)

    // Insn 2: r1 = map_fd (LD_IMM64)
    insns[2].code = BPF_LD | BPF_IMM | BPF_DW;
    insns[2].dst_reg = 1;
    insns[2].src_reg = 1; // BPF_PSEUDO_MAP_FD
    insns[2].imm = ringbuf_fd;
    // Insn 3: 0 (Part 2)

    // Insn 4: r1 = *(u32 *)(r1 + 0)
    // 61 11 00 00 00 00 00 00
    insns[4].code = BPF_LDX | BPF_MEM | BPF_W;
    insns[4].dst_reg = 1;
    insns[4].src_reg = 1;
    insns[4].off = 0;

    // Insn 5: r2 = r1
    // bf 12 00 00 00 00 00 00
    insns[5].code = BPF_ALU64 | BPF_MOV | BPF_X;
    insns[5].dst_reg = 2;
    insns[5].src_reg = 1;

    // Insn 6: call 132
    // 85 00 00 00 84 00 00 00
    insns[6].code = BPF_JMP | BPF_CALL;
    insns[6].imm = 132;

    // Insn 7: r1 = r0
    // bf 01 00 00 00 00 00 00
    insns[7].code = BPF_ALU64 | BPF_MOV | BPF_X;
    insns[7].dst_reg = 1;
    insns[7].src_reg = 0;

    // Insn 8: exit
    // 95 00 00 00 00 00 00 00
    insns[8].code = BPF_JMP | BPF_EXIT;

    // What about 9-27?
    // Left as zeros (BPF_LD | BPF_IMM | BPF_W) which is invalid?
    // Let's try to load this.

    bpf_prog_load(BPF_PROG_TYPE_SCHED_CLS, insns, 28, "GPL");

    // Wait, if verifier fails with "unreachable 9", I should fix it to emulate the crash.
    // If verifier needs 9 to be reachable, I need to know how instructions 0-8 allow reaching 9.
    // Or I should set insn_cnt to 9.

    printf("Trying with insn_cnt = 9\n");
    bpf_prog_load(BPF_PROG_TYPE_SCHED_CLS, insns, 9, "GPL");

    return 0;
}

